div.div:
app::batch
struct Summary { ok, failed, seconds, failures }
What batch::run returns: the counts, the time, and one line per failed file

preprocessor (mod.rs)
struct Decoded { image, icc_profile }
A decoded, EXIF-oriented image plus the ICC profile it declared

preprocessor::optimizer
struct Optimised { model_input, crop, first, second }
What optimize_both finds

preprocessor (mod.rs)
struct Trims { first, second }
Trim 1's tight box, and trim 2's only if it moved (working coordinates)

preprocessor::optimizer
struct LetterboxReport { kinds, proxy, texture, bars, keep }
What detect_letterbox found

preprocessor::maria_antonieta
struct PhiltrumSession { session, input_name }
The decrypted YuNet model in an ORT session, shared

preprocessor::maria_antonieta
struct Face { score, bbox, landmarks }
One detected face

center_and_stretch::grazes
struct Blocked { top, bottom, left, right, patch }
Per edge, one flag per line of the original: true = the product grazes there

center_and_stretch::grazes
struct Edges { top, bottom, left, right }
One flag per edge: true = patch fill, false = plain colour or ramp

center_and_stretch::compose
struct EdgeJob<'a> { edge, first, bands, real, blocked, patch, holes }
What stretch_edge needs to know about one edge of the square (private)

center_and_stretch::gradients
struct Square<'a> { plan, subject, original, mask, blocked }
What blend needs to know about one composed square

center_and_stretch::gradients
struct Layout { red, green, yellow, blue, cyan }
Where each zone's fade starts and ends, in canvas pixels (private)

center_and_stretch::gradients
struct Target { a, b, from, to, along_x }
The colour a zone fades into: a at from, b at to (private)

center_and_stretch::gradients
struct Diagonal { sx, sy, vx, vy }
A fade along a slanted line (private)

center_and_stretch::patch
struct Scene<'a> { mask, origin, orig, margin_px }
What the patch fill needs to know besides the canvas pixels

center_and_stretch::patch
struct Gap { pixels, x0, y0, x1, y1 }
One connected gap (private)

exporter (mod.rs)
struct ShotInputs<'a> { working, mask, class, colors }
What the debug tags need from the classifier; None = no verdict

exporter::colors
struct ShotColors { bgc, fgc }
Each colour as rrggbb when there is one

exporter::colors
struct Hist { count, sum }
5-bit-per-channel histogram with a running colour sum per bin (private)

core::options
struct Options { enable_headcuts }
Headcutting for ALL images; off by default

core::trace
struct Session { owns }
Held for one image's run; dropping it writes log.txt

shot_classifier::birefnet
struct BiRefNetModel { session, config, trace_base, backend, gpu_gate }
One ONNX session on a graphics card or the CPU

shot_classifier::gpu_adapters
struct DXGI_ADAPTER_DESC1 { Description, VendorId, DeviceId, … }
Windows DXGI (private)

shot_classifier::gpu_adapters
struct Unknown { _query_interface, _add_ref, release }
COM base vtable (private)

shot_classifier::gpu_adapters
struct FactoryVtbl { unknown, enum_adapters1, … }
IDXGIFactory1 vtable (private)

shot_classifier::gpu_adapters
struct AdapterVtbl { unknown, get_desc1, … }
IDXGIAdapter1 vtable (private)

shot_classifier::segmentation
struct CroppedModel { model, canvas, crop }
A model shown a crop of the frame that answers for the whole frame

shot_classifier::segmentation
struct Instance { mask, bbox, class_id, confidence }
One segmented subject

shot_classifier::segmentation
struct Mask { width, height, data }
The binary subject mask in working-resolution pixels

shot_classifier::gate
struct EdgeProximity { near }
The edges pass 1 flagged

shot_classifier::refine
struct RefinementInput { working_image, original_image, instance }
Everything pass 2 needs for one instance

shot_classifier::refine
struct EdgeRefinement { edge, touching, crop_region, coverage }
The result of refining one edge

shot_classifier::refine
struct Trimap { width, height, labels }
private; interior / exterior / unknown ring

shot_classifier::geometry
struct EdgeView { inner, edge }
Presents a grid so that one edge reads as the top edge

shot_classifier::geometry
struct BoolSummedArea { width, height, sums }
Prefix sums: is any cell set in this rectangle?

shot_classifier::route
struct Shot<'a> { class, mask, bgc }
One image's verdict, the mask it was read from and the BGC the colour sampler found

shot_classifier::route
enum R1Job: Stretch(SquarePlan) | Reframe { keep, subject }
What R1 is told to do

shot_classifier::route
struct Decision { route, subject, plan, note }
One routing decision

shot_classifier::plan
struct Pins { top, bottom, left, right }
Sides the subject runs off the frame at

shot_classifier::plan
struct SquarePlan { side, x, y }
The output square in original-image pixels

shot_classifier::plan
struct Overhang { top, bottom, left, right }
How far the square reaches past each border
